import { describe, expect, it, vi } from "vitest";
import { domeGeometry } from "../src/astro/light-domes";
import { computeNight } from "../src/astro/night";
import { contiguousRuns, IntegrationNights, nightFromWire, type NightRequest } from "../src/data/integration";
import type { HomeAssistant } from "../src/types";
import fixture from "./fixtures/integration-nights.json";

// Generated by the Milky Way Planner integration's own websocket code (Python), so this also pins the two implementations together.
const KANAB = { latitude: 37.047, longitude: -112.527, elevation: 1500 };

describe("integration wire format", () => {
  const wire = fixture.nights[0];
  const night = nightFromWire(wire as any);

  it("maps into the card's NightSummary", () => {
    expect(night.date).toEqual({ y: 2026, m: 7, d: 11 });
    expect(night.dusk).toBeInstanceOf(Date);
    expect(night.samples.length).toBe(wire.samples!.length);
    expect(night.samples[0].gc.altitude).toBeTypeOf("number");
    expect(night.samples[0].dome.penalty).toBeTypeOf("number");
  });

  it("agrees with the card's own calculation for the same night", () => {
    const req = fixture.request;
    const local = computeNight({ y: 2026, m: 7, d: 11 }, KANAB, {
      minGcAltitude: req.min_gc_altitude,
      maxMoonIllumination: req.max_moon_illumination,
      bortle: req.bortle,
      domes: domeGeometry(KANAB, req.domes),
      domeSigma: req.dome_sigma,
    });
    expect(night.gcMinutes).toBe(local.gcMinutes);
    expect(night.orientation).toBe(local.orientation);
    expect(Math.abs(night.gcStart!.getTime() - local.gcStart!.getTime())).toBeLessThan(1000);
    expect(Math.abs(night.gcEnd!.getTime() - local.gcEnd!.getTime())).toBeLessThan(1000);
    expect(night.domePenalty).toBeCloseTo(local.domePenalty, 3);
    expect(night.moonPhase).toBeCloseTo(local.moonPhase, 3);
    expect(night.samples.filter((s) => s.gcVisible).length).toBe(local.samples.filter((s) => s.gcVisible).length);
  });
});

describe("contiguousRuns", () => {
  it("splits on gaps and the length cap", () => {
    const d = (n: number) => ({ y: 2026, m: 7, d: n });
    expect(contiguousRuns([d(3), d(1), d(2), d(10)]).map((r) => r.map((x) => x.d))).toEqual([[1, 2, 3], [10]]);
    expect(contiguousRuns([d(1), d(2), d(3)], 2).map((r) => r.length)).toEqual([2, 1]);
  });
});

describe("IntegrationNights", () => {
  const req = (day: number): NightRequest => ({
    key: `k|${day}`,
    group: "g",
    date: { y: 2026, m: 7, d: day },
    observer: KANAB,
    bortle: 3,
    minGcAltitude: 10,
    maxMoonIllumination: 10,
    domes: [],
    domeSigma: 25,
  });
  const wireFor = (day: number) => ({ ...fixture.nights[0], date: `2026-07-${String(day).padStart(2, "0")}` });
  const hassWith = (callWS: any, components = ["milky_way_planner"]) => ({ config: { components }, callWS }) as unknown as HomeAssistant;

  it("does nothing when the integration isn't installed", () => {
    const callWS = vi.fn();
    const store = new IntegrationNights(() => {});
    store.request(hassWith(callWS, ["sun"]), req(1));
    expect(callWS).not.toHaveBeenCalled();
  });

  it("batches contiguous nights into one call and serves results by key", async () => {
    const calls: any[] = [];
    const callWS = vi.fn(async (msg: any) => {
      calls.push(msg);
      if (msg.type.endsWith("/info")) return { api_version: 1 };
      return { nights: Array.from({ length: msg.days }, (_, i) => wireFor(Number(msg.start.slice(-2)) + i)) };
    });
    const onChange = vi.fn();
    const store = new IntegrationNights(onChange);
    const hass = hassWith(callWS);
    [1, 2, 3].forEach((d) => store.request(hass, req(d)));
    store.request(hass, req(2)); // duplicate, ignored
    await vi.waitFor(() => expect(onChange).toHaveBeenCalled());
    const nights = calls.filter((c) => c.type.endsWith("/nights"));
    expect(nights).toHaveLength(1);
    expect(nights[0]).toMatchObject({ start: "2026-07-01", days: 3, bortle: 3, min_gc_altitude: 10, step_minutes: 10 });
    expect(store.get("k|2")?.date.d).toBe(2);
  });

  it("falls back quietly (and backs off) when the integration errors", async () => {
    const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
    const callWS = vi.fn(async () => {
      throw new Error("boom");
    });
    const store = new IntegrationNights(() => {});
    const hass = hassWith(callWS);
    store.request(hass, req(1));
    await vi.waitFor(() => expect(warn).toHaveBeenCalled());
    store.request(hass, req(2));
    await Promise.resolve();
    expect(callWS).toHaveBeenCalledTimes(1);
    expect(store.get("k|1")).toBeUndefined();
    warn.mockRestore();
  });
});
